/* Training ring: saber selection, flattened 2D loadout, and turn-based duel. */
.duel-overlay{position:fixed;inset:0;z-index:23;display:grid;place-items:center;padding:16px;background:#050806f2;backdrop-filter:blur(10px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}
.duel-overlay.open{opacity:1;visibility:visible}
.duel-room{position:relative;width:min(1320px,100%);height:min(860px,calc(100vh - 32px));min-height:600px;display:grid;grid-template-rows:62px minmax(0,1fr) 86px;overflow:hidden;border:1px solid #48544a;background:radial-gradient(ellipse at 50% 0,#263129 0,#121814 52%,#0a0f0c 100%);box-shadow:0 30px 120px #000d;color:var(--paper)}
.duel-room[hidden]{display:none}
.duel-room:before{content:"";position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#cbd7c006 1px,transparent 1px),linear-gradient(90deg,#cbd7c006 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(ellipse at 50% 30%,#000,transparent 78%)}
.duel-stage-header{position:relative;z-index:6;display:flex;align-items:center;justify-content:space-between;gap:22px;padding:0 56px 0 28px;border-bottom:1px solid #313d34;background:#121815}
.duel-header-stats{display:flex;align-items:center;gap:20px;font:8px var(--mono);letter-spacing:.13em;color:#7e8a80}
.duel-header-stats b{font-weight:400;color:var(--acid);margin-left:5px}
.duel-lobby-grid{position:relative;z-index:2;display:grid;grid-template-columns:220px minmax(0,1fr) 278px;gap:14px;min-height:0;padding:20px 26px}
.duel-profile,.duel-picker-panel,.duel-preview-panel,.duel-stance-panel{border:1px solid #384239;background:linear-gradient(155deg,#1d251f,#151b17 78%);min-width:0;min-height:0}
.duel-profile{display:flex;flex-direction:column;padding:18px 17px 15px}
.duel-profile .eyebrow,.duel-panel-head .eyebrow{font-size:7px;color:#8d9a8f}
.duel-level-mark{display:flex;align-items:baseline;gap:9px;margin:15px 0 2px}
.duel-level-mark span{font:7px var(--mono);letter-spacing:.16em;color:#7f8b81}
.duel-level-mark b{font:500 38px var(--mono);line-height:.85;letter-spacing:-.08em;color:var(--acid);text-shadow:0 0 26px #d8f36a33}
.duel-profile>strong{font-size:18px;line-height:1.15;letter-spacing:-.04em;font-weight:600;text-transform:uppercase}
.duel-profile>p{margin:8px 0 17px;color:#8d9a90;font-size:9px;line-height:1.7}
.duel-xp{display:grid;gap:6px;padding:12px 0 14px;border-top:1px solid #ffffff0e;border-bottom:1px solid #ffffff0e}
.duel-xp>span{font:8px var(--mono);letter-spacing:.08em;color:#87938a}
.duel-xp>span b{font-weight:500;color:var(--paper)}
.duel-xp>i,.duel-bar{position:relative;display:block;height:6px;overflow:hidden;background:#0b100d;border:1px solid #3a463d}
.duel-xp>i b{display:block;height:100%;width:0;background:linear-gradient(90deg,#8ca244,#d8f36a);box-shadow:0 0 12px #d8f36a66;transition:width .45s}
.duel-record{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin:14px 0 0;background:#ffffff0d}
.duel-record div{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:8px 9px;background:#19201b}
.duel-record small{font:6.5px var(--mono);letter-spacing:.11em;color:#7f8b81}
.duel-record b{font:500 12px var(--mono);color:var(--paper)}
.duel-equal-note{display:flex;align-items:flex-start;gap:8px;margin-top:auto;padding:11px 10px;border-left:1px solid #d8f36a55;background:#101612b8}
.duel-equal-note i{font-style:normal;color:var(--acid);font-size:15px;line-height:1}
.duel-equal-note p{display:grid;gap:3px;margin:0}
.duel-equal-note strong{font:7px var(--mono);letter-spacing:.11em;color:var(--acid)}
.duel-equal-note span{color:#8e9a90;font-size:8.5px;line-height:1.6}
.duel-loadout{display:grid;grid-template-columns:minmax(0,1.04fr) minmax(0,.96fr);gap:12px;min-width:0;min-height:0}
.duel-picker-panel,.duel-preview-panel,.duel-stance-panel{position:relative;overflow:hidden}
.duel-picker-panel{display:grid;grid-template-rows:auto minmax(0,1fr);padding:17px 16px 14px}
.duel-panel-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;padding-bottom:13px;border-bottom:1px solid #ffffff0e}
.duel-panel-head h2{margin:6px 0 0;font-size:21px;line-height:1;letter-spacing:-.055em;font-weight:600}
.duel-panel-head h2 em{font-style:normal;color:var(--acid)}
.duel-panel-head>span{font:7px var(--mono);letter-spacing:.11em;color:#818d84;padding-bottom:2px}
.duel-saber-list{display:flex;flex-direction:column;gap:7px;min-height:0;overflow-y:auto;padding:12px 3px 4px 0;scrollbar-width:thin;scrollbar-color:#566258 #202623}
.duel-saber-card{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:10px;min-height:57px;padding:6px 9px;border:1px solid #354038;background:#19211c;color:var(--paper);font-family:var(--sans);text-align:left;cursor:pointer;transition:border-color .2s,background .2s,transform .2s}
.duel-saber-card:hover,.duel-saber-card:focus-visible{outline:none;border-color:#788764;background:#1e2821;transform:translateX(2px)}
.duel-saber-card.is-selected{border-color:var(--acid);background:linear-gradient(100deg,#242f22,#1c251f);box-shadow:inset 2px 0 0 var(--acid)}
.duel-saber-thumb{width:30px;height:48px;display:block}
.duel-saber-card-copy{display:grid;gap:3px;min-width:0}
.duel-saber-card-copy strong{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-saber-card-copy small{font:6.5px var(--mono);letter-spacing:.06em;color:#7f8b81;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-saber-card-state{font:6.5px var(--mono);letter-spacing:.1em;color:#7f8b81;text-align:right}
.duel-saber-card.is-selected .duel-saber-card-state{color:var(--acid)}
.duel-preview-panel{display:grid;grid-template-rows:minmax(0,1fr) auto;background:radial-gradient(ellipse at 50% 38%,#2c3c31 0,#18221b 56%,#101612 100%)}
.duel-preview-glow{position:absolute;left:50%;top:42%;width:78%;height:66%;transform:translate(-50%,-50%);background:radial-gradient(ellipse,var(--preview-glow,#d8f36a33),transparent 68%);filter:blur(16px);pointer-events:none;opacity:.8}
.duel-preview-panel canvas{position:absolute;inset:0;width:100%;height:100%;z-index:2}
.duel-preview-tag{position:absolute;z-index:3;right:11px;top:11px;padding:5px 7px;border:1px solid #d8f36a33;background:#0b100dbb;color:#a9b694;font:6.5px var(--mono);letter-spacing:.12em;pointer-events:none}
.duel-preview-meta{position:relative;z-index:4;display:grid;gap:4px;margin-top:auto;padding:44px 16px 15px;background:linear-gradient(to top,#0e1410f2 54%,transparent);pointer-events:none}
.duel-preview-meta .eyebrow{font-size:6.5px;color:#8b978d}
.duel-preview-meta strong{font-size:18px;line-height:1.1;letter-spacing:-.045em;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-preview-meta small{font:7px var(--mono);letter-spacing:.06em;color:#8e9a90;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-empty{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:5px;padding:18px 4px}
.duel-empty[hidden]{display:none}
.duel-empty>span{font-size:28px;color:var(--acid);line-height:1}
.duel-empty>strong{font-size:16px;letter-spacing:-.03em}
.duel-empty p{margin:0;color:#8e9a90;font-size:9px;line-height:1.7;max-width:290px}
.duel-empty-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:10px}
.duel-loaner-button{padding:9px 11px;border:1px solid #6f7c62;background:#202a22;color:var(--acid);font:7px var(--mono);letter-spacing:.1em;cursor:pointer}
.duel-loaner-button:hover{border-color:var(--acid);background:#263125}
.duel-stance-panel{display:grid;grid-template-rows:auto minmax(0,1fr) auto;padding:17px 16px 14px}
.duel-stance-list{display:flex;flex-direction:column;gap:8px;min-height:0;overflow-y:auto;padding:12px 2px 4px 0;scrollbar-width:thin;scrollbar-color:#566258 #202623}
.duel-stance-card{position:relative;display:grid;grid-template-columns:30px minmax(0,1fr);gap:9px;align-items:start;padding:11px 10px;border:1px solid #354038;background:#19211c;color:var(--paper);font-family:var(--sans);text-align:left;cursor:pointer;transition:border-color .2s,background .2s}
.duel-stance-card:hover,.duel-stance-card:focus-visible{outline:none;border-color:#788764;background:#1e2821}
.duel-stance-card.is-selected{border-color:var(--acid);background:#222d22;box-shadow:inset 2px 0 0 var(--acid)}
.duel-stance-glyph{display:grid;place-items:center;width:28px;height:30px;border:1px solid #d8f36a33;background:#0f1511;color:var(--acid);font:16px var(--mono)}
.duel-stance-copy{display:grid;gap:3px;min-width:0}
.duel-stance-copy strong{font-size:11px;font-weight:600}
.duel-stance-copy small{font:6.5px var(--mono);letter-spacing:.1em;color:var(--acid)}
.duel-stance-copy span{font-size:8px;line-height:1.5;color:#8e9a90}
.duel-stance-note{margin:10px 0 0;padding-top:10px;border-top:1px solid #ffffff0e;color:#7f8b81;font-size:8px;line-height:1.6}
.duel-room .stage-actions .primary-button:disabled{opacity:.4;cursor:not-allowed;filter:grayscale(.5)}
.duel-overlay .activity-stage-footer{background:#111714}
.duel-overlay .stage-copy .eyebrow{color:var(--acid)}

/* Battle arena */
.duel-arena{grid-template-rows:62px minmax(0,1fr) 104px;background:#080c0a}
.duel-stage{position:relative;min-height:0;overflow:hidden;background:radial-gradient(ellipse at 50% 48%,#24332b 0,#111914 55%,#070b09 100%)}
.duel-stage canvas{position:absolute;inset:0;width:100%;height:100%;z-index:2}
.duel-vignette{position:absolute;inset:0;z-index:3;pointer-events:none;background:radial-gradient(ellipse at center,transparent 40%,#040705c4 100%)}
.duel-round{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:13px;font:7px var(--mono);letter-spacing:.13em;color:#8b978d;white-space:nowrap}
.duel-round b{font-weight:500;color:var(--paper)}
.duel-round i{width:18px;height:1px;background:#465148}
.duel-hud{position:absolute;z-index:5;top:18px;width:min(300px,30%);padding:10px 12px;border:1px solid #ffffff14;background:linear-gradient(130deg,#0b110ee8,#0b110eb8);backdrop-filter:blur(4px);pointer-events:none}
.duel-hud-player{left:23px;border-left:2px solid var(--duel-color,var(--acid))}
.duel-hud-enemy{right:23px;border-right:2px solid var(--duel-enemy-color,#ff5b6b);text-align:right}
.duel-hud-name{display:grid;gap:3px;margin-bottom:9px}
.duel-hud-name .eyebrow{font-size:6.5px;letter-spacing:.11em;color:#849187;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-hud-name .eyebrow b{font-weight:400;color:var(--duel-color,var(--acid))}
.duel-hud-enemy .duel-hud-name .eyebrow b,.duel-hud-enemy .duel-hud-name .eyebrow{color:var(--duel-enemy-color,#ff7a86)}
.duel-hud-name strong{font-size:13px;letter-spacing:-.03em;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-bar{display:flex;align-items:center;height:8px;margin-top:5px}
.duel-bar i{position:absolute;left:1px;top:1px;bottom:1px;width:100%;background:linear-gradient(90deg,#c9df65,#d8f36a);box-shadow:0 0 10px #d8f36a55;transition:width .35s}
.duel-bar span{position:absolute;right:4px;font:6px var(--mono);letter-spacing:.06em;color:#e6ecd9;text-shadow:0 1px 2px #000;z-index:2;mix-blend-mode:normal}
.duel-hud-enemy .duel-bar i{left:auto;right:1px;background:linear-gradient(90deg,#a33944,#ff6a76)}
.duel-hud-enemy .duel-bar span{right:auto;left:4px}
.duel-bar-force{height:6px;margin-top:4px;border-color:#3d5147}
.duel-bar-force i{background:linear-gradient(90deg,#2c7993,#55d7e8);box-shadow:0 0 10px #55d7e855}
.duel-bar-force span{font-size:5.5px;letter-spacing:.09em;color:#caeff2}
.duel-bar-enemy-force i{background:linear-gradient(90deg,#8e3944,#e46070)}
.duel-stance-chip{display:inline-block;margin-top:8px;padding:3px 6px;border:1px solid #d8f36a33;color:var(--acid);font:6px var(--mono);letter-spacing:.13em}
.duel-stance-chip.is-enemy{border-color:#ff5b6b33;color:#ff8a94}
.duel-intent{position:absolute;z-index:5;left:50%;top:18px;transform:translateX(-50%);display:grid;justify-items:center;gap:4px;width:min(320px,33%);padding:8px 12px;border:1px solid #ffffff12;background:#0a100dd9;text-align:center;pointer-events:none;transition:border-color .25s}
.duel-intent .eyebrow{font-size:6px;letter-spacing:.16em;color:#7e8a80}
.duel-intent b{font-size:10px;font-weight:600;color:#dbe3d4}
.duel-intent.is-heavy{border-color:#ff725b55}
.duel-intent.is-heavy b{color:#ff9a86}
.duel-intent.is-force{border-color:#62d9e855}
.duel-intent.is-force b{color:#8fe9f4}
.duel-intent.is-block{border-color:#d8f36a44}
.duel-intent.is-block b{color:var(--acid)}
.duel-intent.is-staggered{border-color:#ffffff22;opacity:.62}
.duel-announce{position:absolute;z-index:6;left:50%;top:24%;transform:translate(-50%,-6px);padding:7px 13px;border:1px solid #d8f36a44;background:#0a100dcc;color:var(--acid);font:8px var(--mono);letter-spacing:.16em;white-space:nowrap;opacity:0;transition:opacity .2s,transform .2s;pointer-events:none}
.duel-announce.show{opacity:1;transform:translate(-50%,0)}
.duel-announce.is-hit{border-color:#ff6b5c55;color:#ff8a7d}
.duel-announce.is-force{border-color:#59d9e855;color:#8fe9f4}
.duel-battle-footer{position:relative;z-index:6;display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2.6fr);gap:18px;padding:12px 26px;border-top:1px solid #313d34;background:#101613}
.duel-log-wrap{display:grid;align-content:start;gap:5px;min-width:0;padding-right:16px;border-right:1px solid #ffffff0e}
.duel-log-wrap .eyebrow{font-size:6.5px;color:#8a968c}
.duel-log{display:flex;flex-direction:column;gap:3px;max-height:61px;overflow:hidden;font-size:8px;line-height:1.4;color:#9da89f}
.duel-log div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.55}
.duel-log div:first-child{opacity:1;color:#d4dccb}
.duel-log div.is-good:first-child{color:var(--acid)}
.duel-log div.is-bad:first-child{color:#ff9a8d}
.duel-log div.is-force:first-child{color:#8fe9f4}
.duel-actions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;min-width:0}
.duel-action{position:relative;display:grid;grid-template-columns:1fr;align-content:start;gap:2px;min-height:58px;padding:8px 9px 7px;border:1px solid #3a463c;background:linear-gradient(155deg,#1e2821,#171e1a);color:var(--paper);font-family:var(--sans);text-align:left;cursor:pointer;transition:border-color .18s,background .18s,transform .18s,opacity .18s}
.duel-action:hover,.duel-action:focus-visible{outline:none;border-color:#a9bf74;background:#243126;transform:translateY(-2px)}
.duel-action:active{transform:translateY(0)}
.duel-action:disabled{opacity:.35;cursor:not-allowed;transform:none;filter:grayscale(.35)}
.duel-action strong{font-size:10px;font-weight:600;letter-spacing:-.01em}
.duel-action small{font:6px var(--mono);letter-spacing:.04em;color:#839077;line-height:1.4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.duel-action-key{position:absolute;right:6px;top:6px;color:#6d7b6e;font:6px var(--mono)}
.duel-action[data-duel-action="heavy"]{border-color:#4b4037}
.duel-action[data-duel-action="heavy"]:hover{border-color:#d69b71}
.duel-action[data-duel-action="block"] small{color:#7f9d94}
.duel-action[data-duel-action="force"]{border-color:#354d4e}
.duel-action[data-duel-action="force"]:hover{border-color:#71d6df}
.duel-action[data-duel-action="force"] small{color:#7eafb3}
.duel-result{position:absolute;inset:0;z-index:8;display:grid;place-items:center;padding:22px;background:#050a07d9;backdrop-filter:blur(7px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}
.duel-result.is-open{opacity:1;visibility:visible}
.duel-result-card{width:min(470px,100%);padding:28px 32px 26px;border:1px solid #59664f;background:linear-gradient(150deg,#1c261f,#111713f7);box-shadow:0 28px 90px #000b;text-align:left}
.duel-result-card .eyebrow{font-size:7px;color:var(--acid)}
.duel-result-card h2{margin:10px 0 8px;font-size:clamp(29px,4vw,42px);line-height:.98;letter-spacing:-.06em;font-weight:600}
.duel-result-card h2 em{font-style:normal;color:var(--acid)}
.duel-result-card p{margin:0;color:#9aa59c;font-size:10px;line-height:1.7}
.duel-result-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:20px 0 18px;background:#ffffff0d}
.duel-result-stats div{display:grid;gap:3px;padding:10px 11px;background:#19201b}
.duel-result-stats small{font:6.5px var(--mono);letter-spacing:.12em;color:#7f8b81}
.duel-result-stats b{font:500 17px var(--mono);color:var(--paper)}
.duel-result-actions{display:flex;align-items:center;gap:18px}
.duel-result-actions .primary-button{font-size:9px;padding:13px 18px}
.duel-result-actions .text-button{font-size:8px}
.duel-result-card.is-victory h2{color:#f1ffcf}
.duel-result-card.is-defeat h2{color:#ffb1a5}
.duel-result-card.is-levelup{border-color:#d8f36a88;box-shadow:0 0 0 1px #d8f36a22,0 28px 90px #000b,0 0 60px #d8f36a22}

@media(max-width:1060px){
  .duel-lobby-grid{grid-template-columns:192px minmax(0,1fr) 246px;gap:10px;padding:16px 18px}
  .duel-loadout{grid-template-columns:minmax(0,1fr) minmax(0,.84fr);gap:9px}
  .duel-profile{padding:14px 13px}
  .duel-level-mark b{font-size:31px}
  .duel-panel-head h2{font-size:18px}
  .duel-preview-meta strong{font-size:15px}
  .duel-header-stats{gap:12px}
  .duel-hud{width:min(270px,31%)}
  .duel-intent{width:min(280px,30%)}
}
@media(max-width:820px){
  .duel-overlay{padding:8px}
  .duel-room{height:calc(100vh - 16px);min-height:0;grid-template-rows:54px minmax(0,1fr) auto;overflow-y:auto}
  .duel-stage-header{padding:0 46px 0 16px}
  .duel-header-stats{gap:10px;font-size:7px}
  .duel-lobby-grid{grid-template-columns:1fr;padding:12px 14px;gap:10px;overflow-y:auto}
  .duel-profile{display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto auto auto;column-gap:16px;align-items:center;padding:12px 13px}
  .duel-profile>.eyebrow{grid-column:1;grid-row:1;align-self:end}
  .duel-level-mark{grid-column:1;grid-row:2/4;margin:2px 0;flex-direction:column;align-items:flex-start;gap:2px}
  .duel-profile>strong{grid-column:2;grid-row:1/3;align-self:end;font-size:16px}
  .duel-profile>p{grid-column:2;grid-row:3;margin:3px 0 0;font-size:8px}
  .duel-xp{grid-column:1/-1;grid-row:4;margin-top:9px}
  .duel-record{grid-column:1/-1;grid-row:5;margin-top:9px}
  .duel-equal-note{display:none}
  .duel-loadout{grid-template-columns:1fr;min-height:0}
  .duel-picker-panel{min-height:210px}
  .duel-preview-panel{min-height:240px}
  .duel-stance-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}
  .duel-stance-card{grid-template-columns:1fr;gap:5px;padding:9px}
  .duel-stance-glyph{width:24px;height:25px;font-size:13px}
  .duel-stance-copy span{display:none}
  .duel-stance-note{display:none}
  .duel-arena{grid-template-rows:54px minmax(320px,1fr) auto}
  .duel-round{position:static;transform:none}
  .duel-stage{min-height:320px}
  .duel-hud{top:10px;width:44%;padding:8px 9px}
  .duel-hud-player{left:10px}
  .duel-hud-enemy{right:10px}
  .duel-hud-name strong{font-size:11px}
  .duel-intent{top:auto;bottom:12px;width:calc(100% - 20px);max-width:none;padding:6px 10px}
  .duel-intent .eyebrow{display:none}
  .duel-announce{top:34%}
  .duel-battle-footer{grid-template-columns:1fr;gap:8px;padding:10px 12px 12px}
  .duel-log-wrap{padding-right:0;border-right:0}
  .duel-log{max-height:34px}
  .duel-log div:nth-child(n+3){display:none}
  .duel-actions{grid-template-columns:repeat(2,minmax(0,1fr))}
  .duel-action{min-height:48px}
  .duel-result-card{padding:22px}
}
@media(max-width:480px){
  .duel-header-stats{display:none}
  .duel-panel-head h2{font-size:17px}
  .duel-picker-panel{min-height:190px}
  .duel-preview-panel{min-height:210px}
  .duel-profile>p{display:none}
  .duel-hud{width:46%;top:8px}
  .duel-hud-name .eyebrow{font-size:5.5px}
  .duel-stance-list{grid-template-columns:1fr}
  .duel-stance-card{grid-template-columns:26px 1fr;gap:7px}
  .duel-announce{font-size:7px}
  .duel-result-actions{flex-direction:column;align-items:stretch;gap:10px}
  .duel-result-actions .primary-button{text-align:center}
}

