  const xpGain = 24 + Math.floor(record.wins / 2) * 4 + Math.min(record.streak, 5) * 2;
  record.wins += 1;
  record.streak += 1;
  record.bestStreak = Math.max(record.bestStreak, record.streak);
  const levels = gainDuelXp(xpGain);
