  $('duelPlayerStance').textContent = `${p.stance.form} · ${p.stance.name.toUpperCase()}`;
  $('duelEnemyHpFill').style.width = `${Math.max(0, e.hp / e.maxHp * 100)}%`;
  $('duelEnemyHpText').textContent = `${Math.max(0, Math.ceil(e.hp))} / ${e.maxHp}`;
