  duel.over = true;
  duel.busy = true;
  updateDuelBattleUI();
  const record = duel.record;
  record.losses += 1;
  record.streak = 0;
  saveDuelRecord();
  playTone(150, .2);
  announceDuel('THE RING WINS THIS ROUND', 'is-hit');
