  $('duelResultStreak').textContent = String(record.streak).padStart(2, '0');
  $('duelNext').innerHTML = victory ? 'NEXT DUEL <span>↗</span>' : 'REMATCH <span>↗</span>';
  $('duelResult').classList.add('is-open');
