  $('duelRound').textContent = String(duel.round).padStart(2, '0');
  $('duelPlayerName').textContent = p.name;
  $('duelPlayerRank').textContent = p.rank.toUpperCase();
  $('duelEnemyName').textContent = e.name;
  $('duelEnemyTier').textContent = e.title;
