const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const artifactParts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [
  { id: 'a1', name: 'Silent Resolve', parts: artifactParts, blade: true, value: 2400, createdAt: new Date().toISOString() },
  { id: 'a2', name: 'Wandering Dawn', parts: artifactParts, blade: true, value: 2400, createdAt: new Date().toISOString() }
];
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  await ctx.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
  const page = await ctx.newPage();
  await page.goto('http://localhost:8123/index.html');
  await page.waitForTimeout(2500);
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(600);
  const boxes = await page.evaluate(() => {
    const sel = ['.duel-lobby-grid', '.duel-profile', '.duel-loadout', '.duel-picker-panel', '.duel-preview-panel', '#duelSaberPreview', '.duel-stance-panel', '#duelStanceList', '.duel-stance-card'];
    return sel.map(s => {
      const el = document.querySelector(s);
      if (!el) return { s, missing: true };
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return { s, x: r.x, y: r.y, w: r.width, h: r.height, pos: cs.position, overflow: cs.overflow, z: cs.zIndex };
    });
  });
  console.log(JSON.stringify(boxes, null, 1));
  const stance = await page.locator('#duelStanceList .duel-stance-card').nth(1).boundingBox();
  console.log('stance box', stance);
  console.log('element at stance center', await page.evaluate(({ x, y }) => {
    const el = document.elementFromPoint(x, y);
    return el ? el.tagName + '#' + el.id + '.' + el.className : null;
  }, { x: stance.x + stance.width / 2, y: stance.y + stance.height / 2 }));
  await page.evaluate(() => document.querySelector('.duel-stance-panel').scrollIntoView());
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/shots/mobile-debug.png' });
  const stance2 = await page.locator('#duelStanceList .duel-stance-card').nth(1).boundingBox();
  console.log('after scroll stance box', stance2, 'at center:', await page.evaluate(({ x, y }) => {
    const el = document.elementFromPoint(x, y); return el ? el.tagName + '#' + el.id + '.' + el.className : null;
  }, { x: stance2.x + stance2.width / 2, y: stance2.y + stance2.height / 2 }));
  await browser.close();
})();

