    round: await page.textContent('#duelRound'),
    php: await page.textContent('#duelPlayerHpText'),
    ehp: await page.textContent('#duelEnemyHpText'),
    force: await page.textContent('#duelPlayerForceText'),
    intent: await page.textContent('#duelIntent b'),
    result: await page.locator('#duelResult').evaluate(el => el.classList.contains('is-open'))
  });
  console.log('start', await hud());
  for (let i = 0; i < 8; i++) {
    await page.keyboard.press(i === 0 ? '4' : '2');
    await page.waitForTimeout(2300);
    const h = await hud();
    console.log('after key', i, h);
    if (h.result) break;
  }
  const rec = await page.evaluate(() => localStorage.getItem('sabersmith.duel.v1'));
  console.log('record', rec);
  console.log('errors', errs);
  await page.screenshot({ path: '/tmp/opencode/shots/keyboard-test.png' });
  await browser.close();
})();

