const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [{ id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 2400, createdAt: new Date().toISOString() }];

async function openArena(page) {
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(500);
  await page.click('#duelStart');
  await page.waitForTimeout(1000);
}
const resultOpen = page => page.locator('#duelResult').evaluate(el => el.classList.contains('is-open'));

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await context.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
  const page = await context.newPage();
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  await page.goto('http://localhost:8123/index.html');
  await page.waitForTimeout(2500);

  await openArena(page);
  // Win up to 3 duels via NEXT DUEL
  for (let duelNo = 1; duelNo <= 3; duelNo++) {
    let outcome = null;
    for (let i = 0; i < 40 && !outcome; i++) {
      if (await resultOpen(page)) { outcome = true; break; }
      await page.keyboard.press('2');
      await page.waitForTimeout(2100);
    }
    outcome = await resultOpen(page);
    const title = outcome ? await page.textContent('#duelResultTitle') : 'NONE';
    const lvl = await page.textContent('#duelResultLevel');
    const xp = await page.textContent('#duelResultXp');
    console.log(`DUEL ${duelNo}: result=${outcome} title="${title}" xp=${xp} level=${lvl}`);
    if (duelNo < 3) {
      await page.click('#duelNext');
      await page.waitForTimeout(1100);
    }
  }
  const recAfter = await page.evaluate(() => JSON.parse(localStorage.getItem('sabersmith.duel.v1')));
  console.log('RECORD AFTER 3', recAfter);

  // Leave, reload, verify persistence + profile UI
  await page.click('#duelLeave');
  await page.waitForTimeout(400);
  await page.click('#duelClose');
  await page.waitForTimeout(300);
  await page.reload();
  await page.waitForTimeout(2500);
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(500);
  console.log('AFTER RELOAD header level =', await page.textContent('#duelHeaderLevel'),
    '| profile rank =', await page.textContent('#duelProfileRank'),
    '| wins =', await page.textContent('#duelWins'),
    '| streak =', await page.textContent('#duelStreak'));

  // Defeat path: use pure block with Djem So until the enemy wins
  await page.locator('#duelStanceList .duel-stance-card').nth(2).click();
  await page.click('#duelStart');
  await page.waitForTimeout(1000);
  let defeated = false;
  for (let i = 0; i < 45 && !defeated; i++) {
    if (await resultOpen(page)) { defeated = true; break; }
    await page.keyboard.press('3');
    await page.waitForTimeout(1700);
  }
  defeated = await resultOpen(page);
  console.log('DEFEAT TEST result open =', defeated,
    '| eyebrow =', defeated ? await page.textContent('#duelResultEyebrow') : '—',
    '| title =', defeated ? await page.textContent('#duelResultTitle') : '—');
  if (defeated) {
    console.log('DEFEAT RECORD', await page.evaluate(() => JSON.parse(localStorage.getItem('sabersmith.duel.v1'))));
    await page.screenshot({ path: '/tmp/opencode/shots/13-defeat.png' });
    await page.click('#duelNext'); // rematch
    await page.waitForTimeout(900);
    console.log('REMATCH after defeat round =', await page.textContent('#duelRound'), 'playerHp =', await page.textContent('#duelPlayerHpText'));
  }
  console.log('PAGE ERRORS', errs.length ? errs : '(none)');
  await browser.close();
})();

