const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [
  { id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 2400, createdAt: new Date().toISOString() },
  { id: 'a2', name: 'Wandering Dawn', parts: { ...parts, hilt: 2, crystal: 5 }, blade: true, value: 2800, createdAt: new Date().toISOString() },
