+.duel-radar i{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--acid);box-shadow:0 0 9px #d8f36a99;animation:duelBlip 2.6s infinite}
+.duel-radar i:nth-child(1){left:67%;top:27%;animation-delay:.3s}
+.duel-radar i:nth-child(2){left:29%;top:63%;animation-delay:1.1s}
+.duel-radar i:nth-child(3){left:58%;top:74%;animation-delay:1.8s}
+.duel-radar i:nth-child(4){left:38%;top:32%;animation-delay:2.2s;opacity:.5}
