input.content:
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [
  { id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 2400, createdAt: new Date().toISOString() },
  { id: 'a2', name: 'Wandering Dawn', parts: { ...parts, hilt: 2, crystal: 5 }, blade: true, value: 2800, createdAt: new Date().toISOString() }
];
async function openDuel(page) {
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(450);
}
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await context.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:8123/index.html');
  await page.waitForTimeout(2400);
  await openDuel(page);
  await page.click('#duelStart');
  await page.waitForTimeout(700);
  console.log('SEARCH', {
    matchVisible: await page.isVisible('#duelMatch'),
    searchVisible: await page.isVisible('#duelMatchSearch'),
    foundHidden: await page.locator('#duelMatchFound').isHidden(),
    tags: await page.locator('#duelMatchTags .duel-match-tag').count(),
    headline: await page.textContent('#duelMatchHeadline'),
    ping: await page.textContent('#duelMatchPing')
  });
  await page.screenshot({ path: '/tmp/opencode/shots/20-match-searching.png' });
  await page.waitForTimeout(2100);
  const found = {
    foundVisible: await page.isVisible('#duelMatchFound'),
    name: await page.textContent('#duelMatchOpponentName'),
    meta: await page.textContent('#duelMatchOpponentMeta'),
    stance: await page.textContent('#duelMatchOpponentStance'),
    playerName: await page.textContent('#duelMatchPlayerName'),
    canvases: await page.evaluate(() => ['duelMatchPlayerSaber', 'duelMatchOpponentSaber'].map(id => {
      const c = document.getElementById(id);
      const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
      let n = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 8) n++;
      return { id, w: c.width, h: c.height, painted: n };
    }))
  };
  console.log('FOUND', found);
  await page.screenshot({ path: '/tmp/opencode/shots/21-match-found.png' });
  await page.waitForTimeout(3000);
  console.log('ARENA', {
    visible: await page.isVisible('#duelArena'),
    matchHidden: await page.locator('#duelMatch').isHidden(),
    enemyName: await page.textContent('#duelEnemyName'),
    header: await page.textContent('#duelArenaOpponent'),
    round: await page.textContent('#duelRound')
  });
  await page.screenshot({ path: '/tmp/opencode/shots/22-arena-intro.png' });
  const record = await page.evaluate(() => JSON.parse(localStorage.getItem('sabersmith.duel.v1')));
  console.log('RECORD used counts', record.opponentNames.length, record.opponentLooks.length, 'name', record.opponentNames.at(-1));

  // Finish the duel quickly, then NEXT DUEL should re-enter matchmaking
  for (let i = 0; i < 30; i++) {
    if (await page.locator('#duelResult').evaluate(el => el.classList.contains('is-open'))) break;
    await page.keyboard.press('2');
    await page.waitForTimeout(2000);
  }
  await page.click('#duelNext');
  await page.waitForTimeout(650);
  console.log('NEXT MATCH', {
    matchVisible: await page.isVisible('#duelMatch'),
    resultHidden: await page.locator('#duelResult').evaluate(el => !el.classList.contains('is-open')),
    searchVisible: await page.isVisible('#duelMatchSearch')
  });
  await page.waitForTimeout(2200);
  const secondName = await page.textContent('#duelMatchOpponentName');
  const secondMeta = await page.textContent('#duelMatchOpponentMeta');
  console.log('SECOND FOUND', secondName, secondMeta);
  await page.screenshot({ path: '/tmp/opencode/shots/23-match-found-second.png' });
  const rec2 = await page.evaluate(() => JSON.parse(localStorage.getItem('sabersmith.duel.v1')));
  console.log('UNIQUE', new Set(rec2.opponentNames).size === rec2.opponentNames.length, new Set(rec2.opponentLooks).size === rec2.opponentLooks.length, rec2.opponentNames);
  console.log('ERRORS', errors.length ? errors : '(none)');
  await browser.close();
})();

