input.content:
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [
  { id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 2400, createdAt: new Date().toISOString() },
  { id: 'a2', name: 'Wandering Dawn', parts: { ...parts, hilt: 2, crystal: 5 }, blade: true, value: 2800, createdAt: new Date().toISOString() }
];
async function enterMatch(page) {
  await page.click('#duelStart');
  await page.waitForTimeout(700);
}
async function waitArena(page) {
  await page.waitForSelector('#duelArena:not([hidden])', { timeout: 8000 });
  await page.waitForTimeout(500);
}
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await context.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:8123/index.html');
  await page.waitForTimeout(2300);
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(400);

  // Full matchmaking flow
  await enterMatch(page);
  const searching = {
    match: await page.isVisible('#duelMatch'),
    search: await page.isVisible('#duelMatchSearch'),
    foundHidden: await page.locator('#duelMatchFound').isHidden(),
    tags: await page.locator('#duelMatchTags .duel-match-tag').count()
  };
  await page.waitForTimeout(1700);
  const found = {
    searchHidden: await page.locator('#duelMatchSearch').isHidden(),
    found: await page.isVisible('#duelMatchFound'),
    title: await page.textContent('#duelMatchTitle'),
    name: await page.textContent('#duelMatchOpponentName'),
    meta: await page.textContent('#duelMatchOpponentMeta'),
    heading: await page.textContent('.duel-found-heading h2')
  };
  await waitArena(page);
  const enemyName = await page.textContent('#duelEnemyName');
  console.log('MATCH FLOW', { searching, found, enemyName, sameName: found.name === enemyName });
  await page.screenshot({ path: '/tmp/opencode/shots/40-arena-final.png' });

  // Fight to a result, using buttons once then keys
  let result = false;
  for (let i = 0; i < 30; i++) {
    if (await page.locator('#duelResult').evaluate(el => el.classList.contains('is-open'))) { result = true; break; }
    if (i === 0) await page.click('#duelActions [data-duel-action="heavy"]');
    else await page.keyboard.press(i % 3 === 0 ? '2' : '1');
    await page.waitForTimeout(2000);
  }
  result = await page.locator('#duelResult').evaluate(el => el.classList.contains('is-open'));
  console.log('RESULT', result, result ? await page.textContent('#duelResultTitle') : '');
  await page.screenshot({ path: '/tmp/opencode/shots/41-result-final.png' });

  // Next duel must go through matchmaking and produce a different opponent
  await page.click('#duelNext');
  await page.waitForTimeout(650);
  const nextSearch = await page.isVisible('#duelMatchSearch');
  await page.waitForTimeout(1700);
  const nextName = await page.textContent('#duelMatchOpponentName');
  const nextMeta = await page.textContent('#duelMatchOpponentMeta');
  console.log('NEXT DUEL MATCH', { nextSearch, nextName, differentName: nextName !== found.name, nextMeta });

  // Cancel during found -> lobby
  await page.click('#duelMatchCancel');
  await page.waitForTimeout(400);
  console.log('CANCEL', { lobby: await page.isVisible('#duelLobby'), matchHidden: await page.locator('#duelMatch').isHidden(), screen: await page.evaluate(() => document.querySelector('#duelStart').disabled) });

  // Reload and ensure record arrays persist and profile still loads
  await page.reload();
  await page.waitForTimeout(2300);
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(400);
  const record = await page.evaluate(() => JSON.parse(localStorage.getItem('sabersmith.duel.v1')));
  console.log('PERSIST', {
    level: await page.textContent('#duelHeaderLevel'),
    wins: await page.textContent('#duelWins'),
    names: record.opponentNames.length,
    looks: record.opponentLooks.length,
    uniqueNames: new Set(record.opponentNames).size === record.opponentNames.length,
    uniqueLooks: new Set(record.opponentLooks).size === record.opponentLooks.length
  });
  console.log('ERRORS', errors.length ? errors : '(none)');
  await browser.close();
})();

