const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [{ id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 1 }];
async function run(browser, width, height, tag) {
  const context = await browser.newContext({ viewport: { width, height } });
  await context.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:8123/index.html');
  await page.waitForTimeout(2200);
  await page.click('#activitiesButton');
  await page.click('#activityDuel');
  await page.waitForTimeout(500);
  await page.click('#duelStart');
  await page.waitForTimeout(2400);
  const found = await page.evaluate(() => {
    const stage = document.querySelector('#duelMatchStage');
    const found = document.querySelector('#duelMatchFound');
    return {
      doc: document.documentElement.scrollWidth,
      viewport: innerWidth,
      foundScroll: found.scrollHeight,
      stageH: stage.clientHeight,
      name: document.querySelector('#duelMatchOpponentName').textContent,
      stance: document.querySelector('#duelMatchOpponentStance').textContent
    };
  });
  await page.screenshot({ path: `/tmp/opencode/shots/70-${tag}-found.png` });
  await page.waitForSelector('#duelArena:not([hidden])', { timeout: 8000 });
  await page.waitForTimeout(600);
  const arena = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, enemy: document.querySelector('#duelEnemyName').textContent }));
  // land a hit and capture combat state
  await page.click('#duelActions [data-duel-action="heavy"]');
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/shots/71-${tag}-combat.png` });
  // finish quickly
  let open = false;
  for (let i = 0; i < 40; i++) {
    open = await page.evaluate(() => document.querySelector('#duelResult').classList.contains('is-open'));
    if (open) break;
    await page.keyboard.press(i % 2 ? '2' : '1');
    await page.waitForTimeout(1900);
  }
  const result = await page.evaluate(() => ({
    open: document.querySelector('#duelResult').classList.contains('is-open'),
    title: document.querySelector('#duelResultTitle').textContent,
    overlayDoc: document.documentElement.scrollWidth,
    cardH: Math.round(document.querySelector('.duel-result-card').getBoundingClientRect().height),
    overlayH: Math.round(document.querySelector('.duel-result').getBoundingClientRect().height)
  }));
  await page.screenshot({ path: `/tmp/opencode/shots/72-${tag}-result.png` });
  await page.click('#duelNext');
  await page.waitForTimeout(600);
  const next = await page.evaluate(() => ({
    search: !document.querySelector('#duelMatchSearch').hidden,
    match: !document.querySelector('#duelMatch').hidden
  }));
  await page.click('#duelMatchCancel');
  await page.waitForTimeout(350);
  const lobby = await page.evaluate(() => ({
    lobby: !document.querySelector('#duelLobby').hidden,
    matchHidden: document.querySelector('#duelMatch').hidden,
    doc: document.documentElement.scrollWidth
  }));
  console.log(tag, JSON.stringify({ found, arena, result, next, lobby, errors: errors.length ? errors : 'none' }, null, 1));
  await context.close();
}
(async () => {
  const browser = await chromium.launch();
  await run(browser, 1440, 900, 'desktop');
  await run(browser, 390, 844, 'mobile');
  await run(browser, 1024, 768, 'tablet');
  await browser.close();
})();

